# per-game evidence pages. The condensed cells are an editorial reading of apps.json / findings.md; the record wins where they differ.
from common import *
import json
A=json.load(open(f"{P}/../apps.json"))
UIT={"isometric world":"isometric","top-down world":"top-down","side-on single scene":"single scene","creature in a room":"creature","map":"map","minimal stat/figure":"minimal","minimal stat":"minimal"}
ROWS={
"growagarden":dict(shot=3,meta="Roblox · 2025 · free, Robux for shortcuts",grows="One square plot. Buy seeds with Sheckles, plant, wait, harvest, sell, buy rarer seeds. Crops grow in real time while you are logged out.",stop="Nothing withers, ever; the store blurb is “your garden literally grows while you are offline”. Absence costs only the global weather events you were not there for.",earn="Sheckles from selling crops → seeds, gear, pet eggs. Weather mutations multiply a crop's value by tens or hundreds.",sig="Plant, log out, trust the plot. Then stand in your garden during a live weather event with the right gear placed.",lesson="Copy the asymmetry: away time grows, presence multiplies. Avoid the weekly event treadmill its own developer admitted was burning players out."),
"stardew":dict(shot=4,meta="ConcernedApe · 2016, iOS 2018 · £4.99, no purchases",grows="A farm, tile by tile, and the farmer: five skills, twelve villagers, four 28-day seasons.",stop="Unwatered crops do not die, they stop growing. Loss comes only from the season boundary you were warned about, lightning, or crows. Close the app for six months and nothing has changed.",earn="Gold from shipping → seeds, tools, buildings. The best reward is the sprinkler, which removes the daily chore you have been doing by hand.",sig="Going to bed: the overnight tally, the level-up jingle, a clean morning. And the watering-can sweep along a row.",lesson="Stall, never kill. And reward the client who has done the work by hand with less to do, not more."),
"hayday":dict(shot=1,meta="Supercell · 2012 · free, diamonds for speed",grows="An isometric farm: fields, animals, bakery, dairy, orders by truck and boat.",stop="“It never rains here, but the crops never die.” After 31 days away the game pays you to come back: free barn and silo upgrades, animals fed. Players lapse on purpose to collect it.",earn="Coins → seeds, animals, buildings. The squeeze is the barn: full storage, not dead crops, is the urgency.",sig="One finger dragged across a ripe field cuts the whole row; dragged back, it sows again.",lesson="Capacity beats decay as a pressure. The Derby, an opt-in weekly team challenge with a cooldown, is the shape for a trainer's challenge."),
"farmville2":dict(shot=1,meta="Zynga · 2014 · free, keys for speed",grows="A coastal farm with workshops and farm hands you send out to forage.",stop="No withering. The original FarmVille (2009–2020) withered crops and sold a $42 Unwither Ring to switch the punishment off; the mobile successor dropped decay entirely.",earn="Coins → seeds and buildings; keys, mostly bought, skip timers. Keys “essential for expanding” is the top complaint.",sig="Sending a farm hand down the coast road and getting back a bag of rarities you could not have grown.",lesson="The FarmVille arc is the case against decay: the punishment that made it famous is the thing it had to sell a cure for."),
"township":dict(shot=4,meta="Playrix · 2012 · free, T-Cash for speed",grows="A town and a farm: crops → factories → helicopter, train and plane orders → more town.",stop="No decay and no streak. The barn fills up instead, and refills within hours of every upgrade; it is the top complaint and the top conversion mechanic at once.",earn="Coins → buildings and territory; T-Cash skips timers. Three currencies plus building materials.",sig="A sickle dragged across a ripe field. Buildings float a thought-bubble of what they want.",lesson="Copy the thought-bubble: the whole screen becomes one glanceable instruction. Avoid the density and the team Regatta that kicks people for not keeping up."),
"gardenscapes":dict(shot=2,meta="Playrix · 2016 · free, coins for boosters",grows="A derelict estate garden restored task by task. The game is match-3; the garden is the receipt for having played it.",stop="Nothing decays; lives refill while you are away. The only cost of absence is missed timed events, which players call “a stack of popups” to dismiss.",earn="One level won is exactly one star, and stars cannot be bought at any price. Coins, which can, reach only boosters. Bank stars and spend them in one go with Complete the Day.",sig="Spending a star and watching one corner of the garden change, before and after.",lesson="RepGarden's exact architecture: unrelated effort buys garden progress. Keep one unit of effort to one star, keep money out. Avoid the conveyor belt where an evening's grind buys “a bench”."),
"pocketcamp":dict(shot=3,meta="Nintendo · 2017, Complete 2024 · one-off purchase",grows="A campsite to decorate, villagers to befriend, a twenty-plot flower garden.",stop="Nothing dies. A neglected flower wilts, which pauses its timer, and one watering resumes it. Seven years of events now repeat on a four-year cycle, so nothing is missed for good.",earn="Bells → crafting and furniture; leaf tokens, no longer purchasable, → fortune cookies.",sig="Handing a villager the exact thing they asked for, every three hours.",lesson="Copy the wilt that pauses rather than kills, and events that come round again rather than expire."),
"neko":dict(shot=1,meta="Hit-Point · 2014 · free, gold fish optional",grows="A yard that cats visit on their own. What accumulates is the catbook and the mementos they leave.",stop="No decay, no streak, no fail state. You can only make the cats happier. The reward is for returning: who showed up while you were out.",earn="Fish left by cats → food and goodies that attract rarer cats. Touching a cat reduces what it leaves.",sig="Opening the app to find cats you did not choose, and tapping the camera.",lesson="Retention without stakes: pay for coming back, not for never missing. A trainer's comment on a filmed set is exactly “who showed up while you were out”."),
"finch":dict(shot=2,meta="Finch Care · 2021 · free, no ads, Plus optional",grows="One bird, yours, hatched from an egg you chose and named. Ticking a goal fills an energy bar; a full bar sends the bird on an adventure, and it comes home at night with a story.",stop="No decay anywhere. Energy resets daily, so a day off is a zero, not a minus. Growth counts adventures completed, not days. Only the opt-in check-in streak can hurt, and it can be switched off or paused.",earn="Rainbow stones from goals → clothes, furniture, dyes, travel. Stones cannot be bought. The complaints are about the subscription price, never the economy.",sig="The bird leaving on its own because your ticks filled the bar, and the two-option conversation when it returns.",lesson="Copy the whole absence architecture: nothing decays, progress counts sessions done, a pause the client switches on. Leave the daily streak out; it is the subject of Finch's most upvoted complaint."),
"forest":dict(shot=1,meta="Seekrtech · 2014 · free, Plus subscription",grows="One tree per focus session, planted permanently into a forest grid by day, week and month.",stop="Nothing rots between sessions and there is no streak. The penalty is inside the session: leave the app before the timer ends and the tree withers, and the dead tree stays in the grid as a record.",earn="Coins per session → species and decorations, and real trees planted. A December 2025 rebuild added daily logins and claim animations, and five-year users left: “it is no longer a focus app, it's part of the problem.”",sig="Pressing Plant and putting the phone face down. The stakes are live the moment the sapling appears.",lesson="A stake the client chose beats a penalty the app imposed. And every tap added to a one-press loop is noticed; in a gym it is multiplied."),
"flora":dict(shot=3,meta="AppFinca · 2018 · free",grows="One plant per session into a garden that is a single row, newest on the right. Over time the row shifts left and leaves a visible gap where you did not plant.",stop="Nothing dies from absence; the gap is the record. In a session, leaving kills the plant, and the loudest complaint is false kills.",earn="Focus time → new species at Grand Tour stops. The Price is a cash stake you set on yourself, charged only if you press “Honor My Price” after a kill; setting it removes your own pause button.",sig="Setting a price and watching the pause button disappear. Joining a friend's live room and growing in parallel.",lesson="If RepGarden ever takes a stake, the client reports the failure themselves. And never assert a failure the app cannot prove: a set done but not logged must not wither anything."),
"plantnanny":dict(shot=4,meta="Sparkful · 2013, v2 2019 · free, clovers optional",grows="One plant in a pot, grown by drinking water. At max level it is moved to the greenhouse and a new one is planted; three in a tree hole attract creatures.",stop="The plant wilts but cannot die. One logged glass revives it, with no repair item or apology. Recovery costs exactly the action that would have prevented it.",earn="Clovers → new plants, pots, decoration. An update removed the daily seed system and the one strategic choice with it; users noticed.",sig="Press and hold the water button and watch it pour. Logging feels like watering.",lesson="The closest model to copy: grow one vegetable, harvest it into a permanent collection, plant the next. The wilt that cannot kill, revived by one logged set, is the absence rule."),
"habitica":dict(shot=1,meta="HabitRPG · 2015 · free, gems optional",grows="A role-playing avatar with HP, XP and gear. Tick a Daily, earn gold; miss one and take damage. Death costs a level and all gold.",stop="The only app in the set that punishes absence, with damage that escalates the longer you stay away. “Missing 1 day makes me feel so bad about the character that I avoid the app for a month.”",earn="Gold → equipment and potions; gems, bought, → quests and pets.",sig="The red damage notification the next morning for what you did not do.",lesson="The design RepGarden must not be. Its scheduler cannot express a real routine: “How about if I want to visit the gym twice a week?”"),
"focusfriend":dict(shot=1,meta="Hank Green · 2025 · free, no ads, Pro optional",grows="A bean that knits socks while you focus. The bean is not what grows; the room is, bought with the socks.",stop="No decay, no streak, no penalty between sessions. Stop a timer early and the bean is “really really sad” and drops its stitches. That is the whole punishment, and it reached number one in five countries.",earn="Socks → hundreds of decorations across rooms. The top complaint is content exhaustion: the shop is emptied in days.",sig="Starting a timer and watching a bean knit on the lock screen; the needles stopping is the failure signal.",lesson="A sad companion is enough. Plan the catalogue for months, not days: seasonal vegetables, not a shop that empties in a week."),
"brainrot":dict(shot=2,meta="Smolworks · 2025 · subscription",grows="A brain with a health percentage that decays as you use your phone and heals as you stop. One character, one number, one screen.",stop="Inverted: absence from your phone is the win. No streak, no shop, no progression ladder. The complaints are about the hard paywall and unreliable blocking, never about the game.",earn="No currency at all.",sig="The brain getting visibly sicker on the home-screen widget as the day goes on, and the “chat with my brain” gate before a blocked app opens.",lesson="The example of restraint: a reactive figure on a continuous dial needs no economy to work. Too thin to last a twelve-week programme on its own, but the right between-sets layer."),
"pikmin":dict(shot=2,meta="Niantic, now Scopely · 2021 · free, coins optional",grows="Three things at once: seedlings mature into Pikmin after a set number of steps, flowers are planted along the real streets you walk, and fed Pikmin bloom petals you harvest.",stop="No streak, no death, no loss. Only the world expires: planted flowers clear after five days. The one decay punishes over-harvesting a Pikmin, not absence, and the cure is walking.",earn="Petals from Pikmin → flowers planted on the map; nectar from fruit → feeding Pikmin. The loop closes on itself. Coins, bought, reach only storage and event items.",sig="A squad of Pikmin trailing your avatar, and at 9pm the lookback: the day's steps replayed, one photo, a happy or sad face, unscored.",lesson="The closest model to “train and something grows”. Copy the nightly lookback almost literally, and the weekly challenge that pays a participation prize when the group falls short."),
"pokemongo":dict(shot=1,meta="Niantic, now Scopely · 2016 · free, coins for storage and passes",grows="Nothing is tended; a permanent collection accumulates. Walking feeds eggs, buddy candy and weekly distance goals with the app closed.",stop="The collection is a bank: a player back after ten years still had “a couple hundred original 2016 Pokémon sitting safely in my storage”. The daily streaks, by contrast, reset to day one with no freeze.",earn="Stardust and candy → powering up and evolving. Coins, bought, → bag space, incubators, raid passes.",sig="The swipe-flick of a ball at a creature standing on the pavement in front of you.",lesson="Take the background accrual, so a logged session grows something even if the app is closed, and the bank: a permanent collection makes a long absence recoverable in a way a streak never is."),
"zombiesrun":dict(shot=1,meta="Six to Start · 2012 · subscription",grows="A story in your headphones as you run, and underneath it a base, Abel Township, built from supplies collected while moving.",stop="No streak, no decay. Free users unlock one mission a week, so an absent player returns to a backlog of missions, not a penalty.",earn="Supplies picked up automatically → buildings. Its own fans call the base “pointless” because upgrades “produce no tangible effects”.",sig="“Zombies detected.” The voice cutting into your playlist and the sprint that follows: 20% faster for 100 seconds, optional, tunable, can be switched off.",lesson="The opt-in intensity spike with a capped loss is the shape for a trainer's push set. The base is the warning: a reward that changes nothing is noticed within weeks."),
"walkr":dict(shot=1,meta="Sparkful, was Fourdesire · 2014 · free, cubes optional",grows="A galaxy: steps become fuel for a spaceship, fuel discovers planets, planets are levelled and decorated and produce coins while you are away.",stop="An idle game: planets keep producing in your absence and you harvest on return. Absence costs uncollected yield, never loss.",earn="Energy from steps → travel; coins from planets → planet upgrades, satellites, wonders. Three currencies across five systems, and “too complicated” is the top complaint.",sig="Tapping Boost and watching the ship surge: the day's walking spent as fuel in one gesture.",lesson="An idle harvest is a better absence model than a streak: returning is a reward, not a reckoning. The sprawl of its economy is the thing to avoid."),
"sweatcoin":dict(shot=1,meta="Sweatco · 2016 · free, ads, premium",grows="Nothing grows; a wallet fills. Roughly one coin per thousand GPS-verified outdoor steps. Gym steps do not count.",stop="Earning stops, the balance stays. The daily streak's repair is a purchase: “Restore your longest streak, £0.99” is in its in-app list.",earn="Sweatcoins → brand discounts, trials, prize draws. Valued at one to five cents each by its users, and the draws, scratch cards and a spin wheel do the retaining.",sig="The step-to-coin counter ticking over, and the verification that silently discards steps it does not trust.",lesson="The counter-example that justifies the brief: when the reward is external to the activity its value gets measured in pounds, found wanting, and replaced with lotteries and ads."),
"duolingo":dict(shot=6,meta="Duolingo · 2012 · free, ads, Super subscription",grows="A number: the streak, a flame on the home screen, and a path of lesson nodes. Nothing is tended, which is why losing the counter is catastrophic.",stop="One missed day ends the streak. Its own research argues for slack: two equippable freezes lifted daily actives; a weekend amulet made people 4% likelier to return and 5% less likely to break; binge sessions predicted abandonment.",earn="XP ranks you in a weekly league of thirty; gems → freezes and repairs (500 gems). The Streak Wager, an opt-in bet on holding seven days, lifted day-7 retention by 14%.",sig="The flame ticking to the next number with its milestone animation, and the owl's notifications.",lesson="Copy the forgiveness research and reject the “daily” in daily streak. Celebrate early: motivation gain is 50% from day two to three and 0.5% from day 200 to 201."),
"tamagotchi":dict(shot=2,meta="Bandai Namco · 2018 · free, ads and gems",grows="One creature in a room, evolving by how it is cared for: sleep, hunger, play, bathroom.",stop="It cannot die. The 1996 toy died in half a day without care, got banned from schools and buried in toy graveyards; the 2018 app removed death, and a creature ignored for ten days is a healthy adult that “waited patiently”.",earn="Coins from minigames → food, toys, costumes, decorations. Gems skip the sleep timer.",sig="Tapping the toilet to clean up after it. Tickling it.",lesson="A care loop still works when the creature can only look sad. Copy the screen: seven elements, the creature uncontested in the centre."),
}
def row(s):
    r=ROWS[s]; a=A.get(s,{}); ui=UIT.get(a.get("ui_type",""),a.get("ui_type",""))
    return f'''<div style="display:flex;gap:3mm;padding:1.8mm 0;border-bottom:1px solid {LINE};align-items:flex-start">
<div style="flex:none;width:15mm">{shot(s,r["shot"],26,1.5).replace("height:26mm","height:26mm;max-width:15mm;object-fit:cover;width:15mm")}</div>
<div style="flex:1;min-width:0"><div style="display:flex;align-items:center;gap:2mm;margin-bottom:.6mm">{icon(s,16,0)}<b style="font-family:Bricolage Grotesque,sans-serif;font-size:10pt">{SHORT[s]}</b><span class="small">{r["meta"]}</span><span class="tag v" style="margin-left:auto">{ui}</span></div>
<div class="grid2" style="gap:.6mm 4mm;font-size:7.6pt;line-height:1.25;color:#2A3440">
<div><span class="mono" style="font-size:6.5pt">What grows</span><br>{r["grows"]}</div>
<div><span class="mono" style="font-size:6.5pt">When you stop</span><br>{r["stop"]}</div>
<div><span class="mono" style="font-size:6.5pt">Earn → spend</span><br>{r["earn"]}</div>
<div><span class="mono" style="font-size:6.5pt">Signature</span><br>{r["sig"]}</div></div>
<div style="font-size:7.6pt;line-height:1.25;margin-top:.6mm"><span class="mono" style="font-size:6.5pt;color:{VIO}">For RepGarden</span> {r["lesson"]}</div></div></div>'''
def group_page(title, lead, slugs, eyebrow):
    return f'<div class="mono eb">{eyebrow}</div><h2>{title}</h2><p class="dim" style="font-size:9.5pt">{lead}</p>{"".join(row(s) for s in slugs)}'
farmA=group_page("Farms and gardens, one by one.","Nine games where a plot is the thing you tend. Read from each game's own pages and wiki, its GB store listing and its players' threads on 27 October 2026. Screenshots are each game's own listing.",["growagarden","stardew","hayday","farmville2","township"],"Evidence · farm and garden games")
farmB=group_page("Farms and gardens, continued.","",["gardenscapes","pocketcamp","neko","tamagotchi"],"Evidence · farm and garden games")
fitA=group_page("When moving your body is the input.","Five apps where walking or running drives a game world, read the same way as the farms, on the same day.",["pikmin","pokemongo","zombiesrun","walkr","sweatcoin"],"Evidence · activity games")
HAB=[s for s in ["finch","forest","flora","plantnanny","habitica","focusfriend","brainrot"] if s in ROWS]
habA=group_page("When a habit grows a plant or a creature.","Seven apps where a real-life behaviour, from drinking water to not touching your phone, grows something on the screen. These are the closest relatives of a garden that grows when you train.",HAB[:4],"Evidence · habit apps")
habB=group_page("Habit apps, continued, and the baseline.","Duolingo is included here because every streak, league and freeze in the set descends from it.",HAB[4:]+["duolingo"],"Evidence · habit apps")
EVIDENCE=[(farmA,"Evidence · farms"),(farmB,"Evidence · farms"),(habA,"Evidence · habit apps"),(habB,"Evidence · habit apps"),(fitA,"Evidence · activity games")]
